-- "مصادر الحل" (solution sources): SolutionSources = per teacher + school year,
-- and ContactMessages gets an optional source + page + question number.
--
-- Safe to run multiple times (IF NOT EXISTS everywhere). Matches the
-- AddSolutionSources migration exactly -- run ONE of the two against a given
-- database, never both.

CREATE TABLE IF NOT EXISTS "SolutionSources" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TeacherId" integer NOT NULL,
    "SchoolYear" integer NOT NULL,
    "Name" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL
);

ALTER TABLE "ContactMessages" ADD COLUMN IF NOT EXISTS "SolutionSourceId" integer NULL;
ALTER TABLE "ContactMessages" ADD COLUMN IF NOT EXISTS "PageNumber" text NULL;
ALTER TABLE "ContactMessages" ADD COLUMN IF NOT EXISTS "QuestionNumber" text NULL;

CREATE INDEX IF NOT EXISTS "IX_SolutionSources_TeacherId_SchoolYear" ON "SolutionSources" ("TeacherId", "SchoolYear");
CREATE INDEX IF NOT EXISTS "IX_ContactMessages_SolutionSourceId" ON "ContactMessages" ("SolutionSourceId");

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'FK_ContactMessages_SolutionSources_SolutionSourceId'
    ) THEN
        ALTER TABLE "ContactMessages"
            ADD CONSTRAINT "FK_ContactMessages_SolutionSources_SolutionSourceId"
            FOREIGN KEY ("SolutionSourceId") REFERENCES "SolutionSources" ("Id") ON DELETE SET NULL;
    END IF;
END $$;
